+const EQUAL = 0;
+const DELETE = 1;
+const INSERT = 2;
+
+function diffLines(a, b) {
+  if (!Array.isArray(a) || !Array.isArray(b)) {
+    throw new TypeError('diffLines expects two arrays of strings');
+  }
+  // Intern lines so the hot loops compare small integers instead of strings.
+  const ids = new Map();
+  const intern = (lines) => {
+    const out = new Int32Array(lines.length);
+    for (let i = 0; i < lines.length; i++) {
+      let id = ids.get(lines[i]);
+      if (id === undefined) {
+        id = ids.size;
+        ids.set(lines[i], id);
+      }
+      out[i] = id;
+    }
+    return out;
+  };
+  const x = intern(a);
+  const y = intern(b);
+  const ops = [];
+  diffRange(x, 0, x.length, y, 0, y.length, ops);
+
+  // Materialize, moving all deletes ahead of inserts within each change run.
+  const script = [];
+  let i = 0;
+  let j = 0;
+  for (let k = 0; k < ops.length;) {
+    if (ops[k] === EQUAL) {
+      script.push({ op: 'equal', line: a[i] });
+      i++;
+      j++;
+      k++;
+      continue;
+    }
+    let deletes = 0;
+    let inserts = 0;
+    for (; k < ops.length && ops[k] !== EQUAL; k++) {
+      if (ops[k] === DELETE) deletes++;
+      else inserts++;
+    }
+    for (; deletes > 0; deletes--) script.push({ op: 'delete', line: a[i++] });
+    for (; inserts > 0; inserts--) script.push({ op: 'insert', line: b[j++] });
+  }
+  return script;
+}
+
+/** Append a minimal edit script for x[aLo, aHi) -> y[bLo, bHi) to ops. */
+function diffRange(x, aLo, aHi, y, bLo, bHi, ops) {
+  while (aLo < aHi && bLo < bHi && x[aLo] === y[bLo]) {
+    ops.push(EQUAL);
+    aLo++;
+    bLo++;
+  }
+  let suffix = 0;
+  while (aLo < aHi && bLo < bHi && x[aHi - 1] === y[bHi - 1]) {
+    aHi--;
+    bHi--;
+    suffix++;
+  }
+  const split = aLo < aHi && bLo < bHi ? bisect(x, aLo, aHi, y, bLo, bHi) : null;
+  if (split !== null) {
+    diffRange(x, aLo, split[0], y, bLo, split[1], ops);
+    diffRange(x, split[0], aHi, y, split[1], bHi, ops);
+  } else {
+    // One side is empty, or the ranges share no line (bisect found no snake).
+    for (let i = aLo; i < aHi; i++) ops.push(DELETE);
+    for (let j = bLo; j < bHi; j++) ops.push(INSERT);
+  }
+  for (; suffix > 0; suffix--) ops.push(EQUAL);
+}
+
+/**
+ * Myers' middle-snake search in linear space. Returns the absolute [i, j]
+ * where the forward and reverse D-paths overlap, or null if the ranges have
+ * no common line. Callers strip common prefix/suffix first, so both halves of
+ * a split have strictly fewer edits than the whole.
+ */
+function bisect(x, aLo, aHi, y, bLo, bHi) {
+  const n = aHi - aLo;
+  const m = bHi - bLo;
+  const maxD = (n + m + 1) >> 1;
+  const offset = maxD + 1;
+  const size = 2 * maxD + 3;
+  const v1 = new Int32Array(size).fill(-1);
+  const v2 = new Int32Array(size).fill(-1);
+  v1[offset + 1] = 0;
+  v2[offset + 1] = 0;
+  const delta = n - m;
+  const front = (delta & 1) !== 0;
+  let k1start = 0;
+  let k1end = 0;
+  let k2start = 0;
+  let k2end = 0;
+  for (let d = 0; d <= maxD; d++) {
+    for (let k1 = -d + k1start; k1 <= d - k1end; k1 += 2) {
+      const i1 = offset + k1;
+      let x1 = k1 === -d || (k1 !== d && v1[i1 - 1] < v1[i1 + 1]) ? v1[i1 + 1] : v1[i1 - 1] + 1;
+      let y1 = x1 - k1;
+      if (x1 >= 0 && y1 >= 0) {
+        while (x1 < n && y1 < m && x[aLo + x1] === y[bLo + y1]) {
+          x1++;
+          y1++;
+        }
+      }
+      v1[i1] = x1;
+      if (x1 > n) {
+        k1end += 2;
+      } else if (y1 > m) {
+        k1start += 2;
+      } else if (front) {
+        const i2 = offset + delta - k1;
+        if (i2 >= 0 && i2 < size && v2[i2] !== -1 && x1 >= n - v2[i2]) {
+          return [aLo + x1, bLo + y1];
+        }
+      }
+    }
+    for (let k2 = -d + k2start; k2 <= d - k2end; k2 += 2) {
+      const i2 = offset + k2;
+      let x2 = k2 === -d || (k2 !== d && v2[i2 - 1] < v2[i2 + 1]) ? v2[i2 + 1] : v2[i2 - 1] + 1;
+      let y2 = x2 - k2;
+      if (x2 >= 0 && y2 >= 0) {
+        while (x2 < n && y2 < m && x[aHi - x2 - 1] === y[bHi - y2 - 1]) {
+          x2++;
+          y2++;
+        }
+      }
+      v2[i2] = x2;
+      if (x2 > n) {
+        k2end += 2;
+      } else if (y2 > m) {
+        k2start += 2;
+      } else if (!front) {
+        const k1 = delta - k2;
+        const i1 = offset + k1;
+        if (i1 >= 0 && i1 < size && v1[i1] !== -1) {
+          const x1 = v1[i1];
+          if (x1 >= n - x2) return [aLo + x1, bLo + x1 - k1];
+        }
+      }
+    }
+  }
+  return null;
+}
