+function unifiedHunks(a, b, { context = 3 } = {}) {
+  if (!Number.isInteger(context) || context < 0) {
+    throw new RangeError('context must be a nonnegative integer');
+  }
+  const script = diffLines(a, b);
+  const len = script.length;
+  // oldAt[k] / newAt[k]: old/new lines preceding script index k.
+  const oldAt = new Int32Array(len + 1);
+  const newAt = new Int32Array(len + 1);
+  for (let k = 0; k < len; k++) {
+    const op = script[k].op;
+    oldAt[k + 1] = oldAt[k] + (op === 'insert' ? 0 : 1);
+    newAt[k + 1] = newAt[k] + (op === 'delete' ? 0 : 1);
+  }
+
+  const hunks = [];
+  const emit = (changeStart, changeEnd) => {
+    const s = Math.max(0, changeStart - context);
+    const e = Math.min(len, changeEnd + context);
+    const lines = new Array(e - s);
+    for (let k = s; k < e; k++) {
+      const { op, line } = script[k];
+      lines[k - s] = (op === 'equal' ? ' ' : op === 'delete' ? '-' : '+') + line;
+    }
+    const oldLines = oldAt[e] - oldAt[s];
+    const newLines = newAt[e] - newAt[s];
+    hunks.push({
+      oldStart: oldLines > 0 ? oldAt[s] + 1 : oldAt[s],
+      oldLines,
+      newStart: newLines > 0 ? newAt[s] + 1 : newAt[s],
+      newLines,
+      lines,
+    });
+  };
+
+  let groupStart = -1;
+  let groupEnd = -1;
+  for (let k = 0; k < len;) {
+    if (script[k].op === 'equal') {
+      k++;
+      continue;
+    }
+    const start = k;
+    while (k < len && script[k].op !== 'equal') k++;
+    if (groupStart === -1) {
+      groupStart = start;
+    } else if (start - groupEnd > 2 * context) {
+      emit(groupStart, groupEnd);
+      groupStart = start;
+    }
+    groupEnd = k;
+  }
+  if (groupStart !== -1) emit(groupStart, groupEnd);
+  return hunks;
+}
