+function applyHunks(a, hunks) {
+  if (!Array.isArray(a) || !Array.isArray(hunks)) {
+    throw new TypeError('applyHunks expects an array of lines and an array of hunks');
+  }
+  const out = [];
+  let pos = 0; // first original index not yet copied or consumed
+  for (let h = 0; h < hunks.length; h++) {
+    const fail = (why) => new Error(`hunk ${h} does not apply: ${why}`);
+    const hunk = hunks[h];
+    if (hunk === null || typeof hunk !== 'object') throw fail('not an object');
+    const { oldStart, oldLines, newStart, newLines, lines } = hunk;
+    for (const v of [oldStart, oldLines, newStart, newLines]) {
+      if (!Number.isInteger(v) || v < 0) throw fail('coordinates must be nonnegative integers');
+    }
+    if (!Array.isArray(lines)) throw fail('lines must be an array');
+    let oldCount = 0;
+    let newCount = 0;
+    for (const line of lines) {
+      if (typeof line !== 'string' || line.length === 0) throw fail('malformed line');
+      const tag = line[0];
+      if (tag === ' ') {
+        oldCount++;
+        newCount++;
+      } else if (tag === '-') {
+        oldCount++;
+      } else if (tag === '+') {
+        newCount++;
+      } else {
+        throw fail(`unknown line prefix ${JSON.stringify(tag)}`);
+      }
+    }
+    if (lines.length === 0) throw fail('hunk has no lines');
+    if (oldCount !== oldLines || newCount !== newLines) throw fail('line counts disagree with header');
+    if (oldLines > 0 && oldStart === 0) throw fail('oldStart must be 1-based');
+    const start = oldLines > 0 ? oldStart - 1 : oldStart;
+    if (start < pos) throw fail('hunks overlap or are out of order');
+    if (start + oldLines > a.length) throw fail('range extends past end of input');
+
+    for (let k = pos; k < start; k++) out.push(a[k]);
+    const expectedNewStart = newLines > 0 ? out.length + 1 : out.length;
+    if (newStart !== expectedNewStart) throw fail(`newStart ${newStart} should be ${expectedNewStart}`);
+    let k = start;
+    for (const line of lines) {
+      const tag = line[0];
+      const text = line.slice(1);
+      if (tag === '+') {
+        out.push(text);
+        continue;
+      }
+      if (a[k] !== text) throw fail(`line ${k + 1} does not match`);
+      if (tag === ' ') out.push(text);
+      k++;
+    }
+    pos = start + oldLines;
+  }
+  for (let k = pos; k < a.length; k++) out.push(a[k]);
+  return out;
+}

