 * Identical inputs return []. Use diffLines' minimality and deletion ordering.
 * Neither input may be mutated. Inputs follow the diffLines contract.
 */
function unifiedHunks(a, b, { context = 3 } = {}) {
  if (!Number.isInteger(context) || context < 0) {
    throw new RangeError('context must be a nonnegative integer');
  }
  const script = diffLines(a, b);
  const len = script.length;
  // oldAt[k] / newAt[k]: old/new lines preceding script index k.
  const oldAt = new Int32Array(len + 1);
  const newAt = new Int32Array(len + 1);
  for (let k = 0; k < len; k++) {
    const op = script[k].op;
    oldAt[k + 1] = oldAt[k] + (op === 'insert' ? 0 : 1);
    newAt[k + 1] = newAt[k] + (op === 'delete' ? 0 : 1);
  }

  const hunks = [];
  const emit = (changeStart, changeEnd) => {
    const s = Math.max(0, changeStart - context);
    const e = Math.min(len, changeEnd + context);
    const lines = new Array(e - s);
    for (let k = s; k < e; k++) {
      const { op, line } = script[k];
      lines[k - s] = (op === 'equal' ? ' ' : op === 'delete' ? '-' : '+') + line;
    }
    const oldLines = oldAt[e] - oldAt[s];
    const newLines = newAt[e] - newAt[s];
    hunks.push({
      oldStart: oldLines > 0 ? oldAt[s] + 1 : oldAt[s],
      oldLines,
      newStart: newLines > 0 ? newAt[s] + 1 : newAt[s],
      newLines,
      lines,
    });
  };

  let groupStart = -1;
  let groupEnd = -1;
  for (let k = 0; k < len;) {
    if (script[k].op === 'equal') {
      k++;
      continue;
    }
    const start = k;
    while (k < len && script[k].op !== 'equal') k++;
    if (groupStart === -1) {
      groupStart = start;
    } else if (start - groupEnd > 2 * context) {
      emit(groupStart, groupEnd);
      groupStart = start;
    }
    groupEnd = k;
  }
  if (groupStart !== -1) emit(groupStart, groupEnd);
  return hunks;
}

/**
 * Return a new array by applying unified hunks to a, without mutating either.
 * Hunk old coordinates refer to the original a: apply in the given order,
 * tracking offsets caused by earlier insertions/deletions. Hunks must be
 * nonoverlapping and ordered; their counts and new coordinates must agree with
 * their lines. Verify every ' ' and '-' line exactly against a before consuming
 * it. Unmentioned original lines are retained. An empty hunk array returns a copy.
 * A mismatch or malformed/nonapplicable hunk throws Error with a message
 * containing 'hunk <index> does not apply', where index is zero-based.
 */
function applyHunks(a, hunks) {
  if (!Array.isArray(a) || !Array.isArray(hunks)) {
    throw new TypeError('applyHunks expects an array of lines and an array of hunks');
  }
  const out = [];
  let pos = 0; // first original index not yet copied or consumed
  for (let h = 0; h < hunks.length; h++) {
    const fail = (why) => new Error(`hunk ${h} does not apply: ${why}`);
    const hunk = hunks[h];
    if (hunk === null || typeof hunk !== 'object') throw fail('not an object');
    const { oldStart, oldLines, newStart, newLines, lines } = hunk;
    for (const v of [oldStart, oldLines, newStart, newLines]) {
      if (!Number.isInteger(v) || v < 0) throw fail('coordinates must be nonnegative integers');
    }
    if (!Array.isArray(lines)) throw fail('lines must be an array');
    let oldCount = 0;
    let newCount = 0;
    for (const line of lines) {
      if (typeof line !== 'string' || line.length === 0) throw fail('malformed line');
      const tag = line[0];
      if (tag === ' ') {
        oldCount++;
        newCount++;
      } else if (tag === '-') {
        oldCount++;
      } else if (tag === '+') {
        newCount++;
      } else {
        throw fail(`unknown line prefix ${JSON.stringify(tag)}`);
      }
    }
    if (lines.length === 0) throw fail('hunk has no lines');
    if (oldCount !== oldLines || newCount !== newLines) throw fail('line counts disagree with header');
    if (oldLines > 0 && oldStart === 0) throw fail('oldStart must be 1-based');
    const start = oldLines > 0 ? oldStart - 1 : oldStart;
    if (start < pos) throw fail('hunks overlap or are out of order');
    if (start + oldLines > a.length) throw fail('range extends past end of input');

    for (let k = pos; k < start; k++) out.push(a[k]);
    const expectedNewStart = newLines > 0 ? out.length + 1 : out.length;
    if (newStart !== expectedNewStart) throw fail(`newStart ${newStart} should be ${expectedNewStart}`);
    let k = start;
    for (const line of lines) {
      const tag = line[0];
      const text = line.slice(1);
      if (tag === '+') {
        out.push(text);
        continue;
      }
      if (a[k] !== text) throw fail(`line ${k + 1} does not match`);
      if (tag === ' ') out.push(text);
      k++;
    }
    pos = start + oldLines;
  }
  for (let k = pos; k < a.length; k++) out.push(a[k]);
  return out;
}

module.exports = { diffLines, unifiedHunks, applyHunks };

